var e={"00":{title:`Installation`,heading:`Branche et trouve la carte`,goal:`Fais dialoguer la chaîne d'outils avec la puce : un câble de données, le bon port USB et le nom d'un port série sur ton Mac.`,learn:[`câble USB-C données vs charge`,`port COM vs USB natif`,`ports série`,`mode boot`],steps:[`Branche un câble USB-C <b>de données</b> sur le port marqué <code>COM</code> (ou <code>UART</code>).`,`Vérifie qu'une LED rouge d'alimentation s'allume.`,`Lance la commande ci-dessus. Un nouveau <code>/dev/cu.usbmodem…</code> ou <code>/dev/cu.wchusbserial…</code> doit apparaître.`,`Donne à Claude le nom du port et dis-lui si ta carte a un ou deux ports USB.`],note:`Le flashage affiche “Failed to connect” ? Maintiens BOOT, appuie sur RST, relâche BOOT, puis flashe à nouveau.`},"01":{title:`Hello`,heading:`Fais connaissance avec la carte`,goal:`Flashe ton premier programme. Il affiche la carte d'identité de la puce et fait défiler les couleurs de l'arc-en-ciel sur la LED RGB de la carte.`,learn:[`setup() et loop()`,`journal série`,`millis()`,`LED RGB WS2812`],pins:{0:{role:`RGB`}},steps:[`Rien à câbler. Laisse le câble sur le port <code>COM</code>.`,`Lance la commande. Attends <code>Hard resetting via RTS pin…</code>.`,`Lis la carte d'identité : la flash doit indiquer <b>16 MB</b>, la PSRAM environ <b>8 MB</b>.`,`Regarde la LED RGB près de la puce passer par toutes les couleurs.`,`Appuie sur <code>Ctrl+C</code> pour quitter le moniteur.`],note:`Pas de couleur sur la LED ? Certaines cartes la relient à GPIO 38. Change PIN_RGB dans kit/include/pins.h.`},"02":{title:`Premier circuit`,heading:`Une LED sur la plaque d'essai`,goal:`Construis ton premier circuit et pilote-le en tapant des commandes. La LED continue son animation pendant que la carte t'écoute.`,learn:[`lignes de la plaque d'essai`,`résistances`,`luminosité en PWM`,`machines à états`],pins:{0:{role:`LED +`},1:{role:`LED −`}},wiring:{rows:[[`GPIO 4`,`résistance 220–330 Ω`,`première patte`],[`résistance`,`patte longue de la LED (+)`,`autre patte, même ligne`],[`patte courte de la LED (−)`,`GND`,`rail bleu ou broche GND`]]},steps:[`Débranche l'USB avant de câbler. Place la carte à cheval sur la rainure centrale de la plaque d'essai.`,`Câble GPIO 4 → résistance → patte longue de la LED. Patte courte de la LED → GND.`,`Rebranche et lance la commande. La LED se met à respirer.`,`Tape <code>blink 200</code>, <code>sos</code>, <code>level 30</code>, <code>on</code>, <code>off</code>.`],note:`Pas encore de résistance ? Le code règle la broche au courant le plus faible (environ 5 mA) par sécurité. Ajoutes-en quand même une bientôt.`}};export{e as default};
